def full_native_log_observation(support, work, result):
    # Reuse the fixed support's complete, same-fd, stable-stat file hasher.
    # No tail, parsing, log rewrite, capsule interpretation or new byte budget.
    observation = {'relative_path': 'phases/capture/native.log',
                   'status': 'NO_CAPTURE_PHASE_RECORDED', 'complete_file_hashed': False,
                   'content_parsed': False, 'capsule_interpreted': False,
                   'retention': 'ORIGINAL_FULL_PHASE_FILE_RETAINED_IN_PLACE', 'byte_cap': MIB}
    if support is not None and work is not None and result.get('stages'):
        observation['identity'] = support.identity(work / 'phases/capture/native.log', MIB)
        observation.update(status='COMPLETE_FILE_IDENTITY_OBSERVED', complete_file_hashed=True)
    return observation


def save_tail(h, work, result, failure, stop, *, support=None):

try:
    result['native_log_observation'] = full_native_log_observation(support, work, result)
except BaseException as observation_error:
    name = type(observation_error).__name__
    result['native_log_observation'] = {
        'relative_path': 'phases/capture/native.log', 'status': 'IDENTITY_UNAVAILABLE',
        'complete_file_hashed': False, 'content_parsed': False, 'capsule_interpreted': False,
        'secondary_error_type': name if name in ('ValueError', 'OSError', 'FileNotFoundError',
            'PermissionError', 'TimeoutError', 'RuntimeError', 'MemoryError') else 'OTHER'}
    if failure is None:
        failure = observation_error
failure = h.save_preserving_failure(work, result, failure)
